-- rowstile 0.1.0-dev: own_names_apart. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'a6029b5885373adb', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a6029b5885373adb' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a6029b5885373adb' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = 'a6029b5885373adb' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '839aa7cb3db0c6be' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '839aa7cb3db0c6be', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- trees built beside the ones in use (by the migration before) take their place
CREATE SCHEMA IF NOT EXISTS authz_keep;
ALTER TABLE authz_int."folder__parent__tree__next" SET SCHEMA authz_keep;
ALTER TABLE authz_keep."folder__parent__tree__next" RENAME TO "folder__parent__tree";
ALTER INDEX authz_keep."folder__parent__tree__next_pkey" RENAME TO "folder__parent__tree_pkey";
ALTER INDEX authz_keep."folder__parent__tree__next_ancestor_idx" RENAME TO "folder__parent__tree_ancestor_idx";

-- the triggers rebuilt trees made on tables their conditions read
DO $authz_dyn$
DECLARE r record;
BEGIN
  FOR r IN SELECT t.tgname, t.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger t
           WHERE t.tgname = ANY (ARRAY['authz_folder__parent__tree_dep']) LOOP
    EXECUTE format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_dyn$;

-- views that change stay where they are, emptied (the same columns, reading nothing) while what they
-- read is dropped and made again; they are defined again below. What the app built on one stays
DO $authz_stub$
DECLARE v text; cols text;
BEGIN
  FOREACH v IN ARRAY ARRAY['authz_int."folder__edit"'] LOOP
    CONTINUE WHEN pg_catalog.to_regclass(v) IS NULL;
    SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = pg_catalog.to_regclass(v) AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
    EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v, cols);
  END LOOP;
END $authz_stub$;

-- the triggers given to the tables under others: made again below, on what this migration makes
-- @locks ACCESS EXCLUSIVE: the partitions and child tables of the tables rowstile watches
DO $authz_ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT g.tgname, g.tgrelid::regclass AS tbl FROM pg_catalog.pg_trigger g
           JOIN pg_catalog.pg_description d ON d.objoid = g.oid AND d.classoid = 'pg_catalog.pg_trigger'::regclass
           WHERE d.description = 'rowstile: the trigger of the table above, for the rows stored here' LOOP
    EXECUTE pg_catalog.format('DROP TRIGGER %I ON %s', r.tgname, r.tbl);
  END LOOP;
END $authz_ch$;

-- what goes, or is made again
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_del" ON "app"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_ins" ON "app"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_trunc" ON "app"."folders";
DROP TRIGGER IF EXISTS "authz_folder__parent__tree_upd" ON "app"."folders";
DROP VIEW IF EXISTS
  authz_int."folder__parent__tree_links",
  authz_int."folder__parent__tree_parents";
DROP FUNCTION IF EXISTS
  authz_int."folder__parent__tree__next_compute"(p_ids bigint[]),
  authz_int."folder__parent__tree_check_loops"(p_ids bigint[]),
  authz_int."folder__parent__tree_compute"(p_ids bigint[]),
  authz_int."folder__parent__tree_on_rows"(),
  authz_int."folder__parent__tree_on_truncate"(),
  authz_int."folder__parent__tree_rebuild"(),
  authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean),
  authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]),
  authz_int."folder__parent__tree_verify"();
DROP INDEX IF EXISTS authz_int."folder__parent__tree_ancestor_idx";
DROP TABLE IF EXISTS
  authz_int."folder__parent__tree",
  authz_int."folder__parent__tree__next";

-- rebuilt inheritance trees start empty
CREATE TEMP TABLE IF NOT EXISTS authz_kept (name text PRIMARY KEY) ON COMMIT DROP;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'conf_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- authz_int.trees: its rows again
DELETE FROM authz_int.trees;
INSERT INTO authz_int.trees VALUES
  ('folder__parent__tree', '80fbccaf636c03a8e2824db0a8664c7e', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid));

-- What else may have changed when objects of a type did: the objects that read them through a relation (a
-- dot, inheritance, a group's members, a group inside a group), then those that read those, until nothing
-- is new. Past 1000 objects of a type: all of them ({*}), and all of what reads them. Each is
-- announced with the cause 'dependent'.
CREATE OR REPLACE FUNCTION authz_int.dependents(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
<<authz__>>
DECLARE
  v_all boolean := '*' = ANY (p_ids);
  v_rows bigint; v_most int;
  -- for each type: the ids known (s), new in the last round (n), found in this one (x), how many were found (c),
  -- and whether it is all of them (a)
  s1 bigint[] := '{}'; n1 bigint[] := '{}'; x1 bigint[]; c1 int := 0; a1 boolean := false;  -- folder
  s2 bigint[] := '{}'; n2 bigint[] := '{}'; x2 bigint[]; c2 int := 0; a2 boolean := false;  -- note
  s3 bigint[] := '{}'; n3 bigint[] := '{}'; x3 bigint[]; c3 int := 0; a3 boolean := false;  -- project
BEGIN
  CASE p_type
    WHEN 'folder' THEN
      IF v_all THEN a1 := true;
      ELSE n1 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s1 := n1;
      END IF;
    WHEN 'project' THEN
      IF v_all THEN a3 := true;
      ELSE n3 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s3 := n3;
      END IF;
    ELSE RETURN;  -- nothing reads its objects
  END CASE;
  LOOP
    -- all of a type: all of what reads it too
    IF a3 THEN a2 := true; END IF;
    EXIT WHEN (a1 OR cardinality(n1) = 0) AND (a2 OR cardinality(n2) = 0) AND (a3 OR cardinality(n3) = 0);
    IF NOT a1 AND (cardinality(n1) > 0) THEN
      v_most := cardinality(s1) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s1)), '{}')
        INTO v_rows, x1
        FROM (SELECT x."id" FROM "app"."folders" x WHERE x."parent_id" = ANY (authz__.n1) AND cardinality(authz__.n1) > 0
          LIMIT authz__.v_most) d(v);
      a1 := v_rows >= v_most;
    ELSE
      x1 := '{}';
    END IF;
    IF NOT a2 AND (cardinality(n3) > 0) THEN
      v_most := cardinality(s2) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s2)), '{}')
        INTO v_rows, x2
        FROM (SELECT x."id" FROM "app"."notes" x WHERE x."project_id" = ANY (authz__.n3) AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a2 := v_rows >= v_most;
    ELSE
      x2 := '{}';
    END IF;
    n1 := x1; s1 := s1 || x1; c1 := c1 + cardinality(x1); a1 := a1 OR c1 > 1000;
    n2 := x2; s2 := s2 || x2; c2 := c2 + cardinality(x2); a2 := a2 OR c2 > 1000;
    n3 := '{}';
  END LOOP;
  IF a1 AND NOT (v_all AND p_type = 'folder') THEN
    PERFORM authz_int.announce('folder', '{*}', 'dependent', false);
  ELSIF NOT a1 AND c1 > 0 THEN
    PERFORM authz_int.announce('folder', ARRAY(SELECT v::text FROM unnest(s1[cardinality(s1) - c1 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a2 AND NOT (v_all AND p_type = 'note') THEN
    PERFORM authz_int.announce('note', '{*}', 'dependent', false);
  ELSIF NOT a2 AND c2 > 0 THEN
    PERFORM authz_int.announce('note', ARRAY(SELECT v::text FROM unnest(s2[cardinality(s2) - c2 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
END $f$;

-- folder: each row with every ancestor it inherits from, through parent
CREATE TABLE authz_int."folder__parent__tree" (descendant bigint NOT NULL, ancestor bigint NOT NULL,
  CONSTRAINT "folder__parent__tree_pkey" PRIMARY KEY (descendant, ancestor));
CREATE INDEX "folder__parent__tree_ancestor_idx" ON authz_int."folder__parent__tree" (ancestor);
INSERT INTO authz_int.locks VALUES ('folder', 0) ON CONFLICT DO NOTHING;
-- kept from the last apply if its definition is the same: its rows are current
DO $k$ BEGIN
  IF to_regclass('authz_keep."folder__parent__tree"') IS NOT NULL THEN
    DROP TABLE authz_int."folder__parent__tree";
    ALTER TABLE authz_keep."folder__parent__tree" SET SCHEMA authz_int;
    INSERT INTO pg_temp.authz_kept VALUES ('folder__parent__tree') ON CONFLICT DO NOTHING;
  END IF;
END $k$;

-- every parent link, from every source
CREATE VIEW authz_int."folder__parent__tree_links" AS
  SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL;

-- walk up from the given rows; a link is followed only if its condition holds on
-- the child, and the parent exists and passes its type's where
CREATE FUNCTION authz_int."folder__parent__tree_compute"(p_ids bigint[]) RETURNS TABLE (o_descendant bigint, o_ancestor bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  WITH RECURSIVE up(_d, _a) AS (
    SELECT x."id", x."id" FROM "app"."folders" x WHERE x."id" = ANY ($1)
    UNION
    SELECT up._d, e._parent
    FROM up
    -- one index lookup per step: joined plainly, a small table gets a full scan at every step
    -- (OFFSET 0 keeps the planner from turning this into a hash join)
    CROSS JOIN LATERAL (SELECT c.* FROM "app"."folders" c WHERE c."id" = up._a OFFSET 0) c
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up._a OFFSET 0)) e
    WHERE (e._link = 0)
      AND EXISTS (SELECT 1 FROM "app"."folders" p WHERE p."id" = e._parent))
  SELECT _d, _a FROM up
$f$;

-- what decides inheritance must be IMMUTABLE
DO $imm$
DECLARE d record;
BEGIN

  FOR d IN SELECT DISTINCT p.oid::regprocedure AS fn
           FROM pg_depend dep
           JOIN pg_rewrite w ON w.oid = dep.objid AND dep.classid = 'pg_rewrite'::regclass
           JOIN pg_proc p ON p.oid = dep.refobjid AND dep.refclassid = 'pg_proc'::regclass
           WHERE w.ev_class IN ('authz_int."folder__parent__tree_links"'::regclass) AND p.provolatile <> 'i' LOOP
    RAISE EXCEPTION '%: a condition used for inheritance calls %, which is not IMMUTABLE; read tables with a subquery instead, so changes to them are tracked [AZ603]',
      'line 31', d.fn;
  END LOOP;
END $imm$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE FUNCTION authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
<<authz__>>
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest($2) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest($1) b(_y) JOIN "app"."folders" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY ($2)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest($1) b(_y) JOIN "app"."folders" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest($2) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "app"."folders" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (authz__.touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (authz__.touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "app"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(batch);
  END LOOP;
END $f$;
CREATE FUNCTION authz_int."folder__parent__tree_on_truncate"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN PERFORM authz_int."folder__parent__tree_rebuild"(); RETURN NULL; END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "app"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."folder__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."folder__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "app"."folders" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the tree's own columns may not loop (links through tables may: they add nothing)
CREATE VIEW authz_int."folder__parent__tree_parents" AS
  SELECT r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL;
CREATE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."folder__parent__tree_parents" e WHERE e._child = ANY ($1)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "app"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'folder % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE ids bigint[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(authz__.ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."folder__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder__parent__tree_ins" AFTER INSERT ON "app"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_upd" AFTER UPDATE ON "app"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_del" AFTER DELETE ON "app"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_rows"();
CREATE TRIGGER "authz_folder__parent__tree_trunc" AFTER TRUNCATE ON "app"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder__parent__tree_on_truncate"();
COMMENT ON TRIGGER "authz_folder__parent__tree_trunc" ON "app"."folders" IS 'rowstile: for a TRUNCATE of the tables under its table too';

-- backfill from the rows already there (unless the tree was kept)
DO $b$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();
  END IF;
END $b$;

-- folder__parent__tree was built beside the one in use, from a snapshot: what changed since is done again
DO $authz_catch_up$
DECLARE v authz_int.next_trees;
BEGIN
  SELECT * INTO v FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
  IF v.name IS NULL OR NOT EXISTS (SELECT 1 FROM pg_temp.authz_kept WHERE name = 'folder__parent__tree') THEN
    RAISE EXCEPTION 'rowstile: folder__parent__tree was not built beside the one in use (the migration before this one does that) [AZ608]';
  END IF;
  IF coalesce((SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to'), 0) > v.feed
     OR (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_txid')
        >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
     OR EXISTS (SELECT 1 FROM authz.changes c WHERE c.object_type = 'folder' AND '*' = ANY (c.object_ids)
                AND c.cause <> 'dependent'
                AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap)) THEN
    PERFORM authz_int."folder__parent__tree_rebuild"();          -- the feed doesn't say everything that changed since: all of it
  ELSE
    PERFORM authz_int."folder__parent__tree_refresh"(ARRAY(SELECT x."id" FROM "app"."folders" x WHERE NOT pg_catalog.pg_visible_in_snapshot(((((pg_catalog.pg_current_xact_id()::text::bigint >> 32) - CASE WHEN x.xmin::text::bigint > (pg_catalog.pg_current_xact_id()::text::bigint & 4294967295) THEN 1 ELSE 0 END) << 32) | x.xmin::text::bigint)::text::xid8, v.snap)
      UNION SELECT y::bigint FROM authz.changes c, unnest(c.object_ids) y
      WHERE c.object_type = 'folder' AND c.cause <> 'dependent'
        AND c.txid >= pg_catalog.pg_snapshot_xmin(v.snap)::text::bigint
        AND NOT pg_catalog.pg_visible_in_snapshot(c.txid::text::xid8, v.snap) AND y <> '*'));
    -- rows deleted since
    DELETE FROM authz_int."folder__parent__tree" d WHERE NOT EXISTS (SELECT 1 FROM "app"."folders" x WHERE x."id" = d.descendant)
                             OR NOT EXISTS (SELECT 1 FROM "app"."folders" x WHERE x."id" = d.ancestor);
  END IF;
  DELETE FROM authz_int.next_trees WHERE name = 'folder__parent__tree';
END $authz_catch_up$;

-- folder.edit (line 35): owner or parent.edit
CREATE OR REPLACE VIEW authz_int."folder__edit" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."folder__edit__start"() s(id));

-- folder.edit for one object (checks of single rows and authz.can)
CREATE OR REPLACE FUNCTION authz_int."folder__edit__has"(p_id bigint) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" c
    WHERE c.descendant = $1
      AND EXISTS (SELECT 1 FROM (
  SELECT id FROM authz_int."folder__owner") s WHERE s.id = c.ancestor));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.projects:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."projects"; r_new "app"."projects";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for app.projects: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.projects', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."projects" x WHERE x."id" = $2::bigint;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.projects: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for app.projects: nobody may update its rows'];
END $f$;

-- app.notes: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."app.notes:seen"(p_id bigint) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = $1)
      OR EXISTS (SELECT 1 FROM "app"."notes" "notes" WHERE "notes"."id" = $1
        AND (SELECT authz_int.scope_cmd('app.notes', 'select')) AND EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = "notes"."project_id"));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.notes:insert:why"(p_row "app"."notes") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.notes:insert:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : project.edit and author  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.notes insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not insert on app.notes'
    ELSE '  no   the sign-in''s scopes do not allow insert on app.notes' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'project.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("notes"."project_id")::text AS id FROM (SELECT ($1).*) AS "notes") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('project', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'author';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.notes:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."notes"; r_new "app"."notes";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.notes:insert:why"(jsonb_populate_record(NULL::"app"."notes", coalesce($3, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.notes', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."notes" x WHERE x."id" = $2::bigint;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.notes:delete:why"(r_old));
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."app.notes:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."app.notes:update:why"(r_new, false) l) END;
END $f$;

