<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT s."project_id" AS id FROM "app"."project_services" s WHERE s."service_id" = (SELECT authz_int."service__me"())) THEN
    RETURN NEXT authz__.pad || 'yes  ' || CASE WHEN $4 IS NULL THEN 'service: a row in app.project_services names you' ELSE 'service: a row in app.project_services names them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'project.service';
