CREATE OR REPLACE FUNCTION authz_int."project__edit__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."project__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'project.edit = owner or member';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."project__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__owner__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."project__member");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'member';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__member__why"($1, p_depth + 1, p_seen, p_asker); END IF;
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."project__view__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."project__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'project.view = edit or service or {public}';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."project__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__edit__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."project__service");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'service';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."project__service__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT r."id" AS id FROM "app"."projects" r WHERE coalesce((public), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{public}';
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."note__author__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT r."id" AS id FROM "app"."notes" r WHERE r."author_id" = (SELECT authz.uid())) THEN
    RETURN NEXT authz__.pad || 'yes  ' || CASE WHEN $4 IS NULL THEN 'author: author_id is you' ELSE 'author: author_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'note.author';
END $f$;

CREATE OR REPLACE FUNCTION authz_int."note__edit__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."note__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'note.edit = author or project.owner';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."note__author");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'author';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."note__author__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."note__project__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'project.owner';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."project__owner" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = $1 AND r."project_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'project', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'project is a project you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'project is project '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has owner' ELSE ', without owner' END;
      IF NOT ('project:owner:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."project__owner__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('project:owner:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."note__view__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."note__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'note.view = project.view';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."note__project__view");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'project.view';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."project_id" AS id FROM "app"."notes" r WHERE r."id" = $1 AND r."project_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'project', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'project is a project you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'project is project '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has view' ELSE ', without view' END;
      IF NOT ('project:view:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."project__view__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('project:view:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

