CREATE OR REPLACE FUNCTION authz_int."folder__edit__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."folder__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'folder.edit = owner or parent.edit';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."folder__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__owner__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."folder__parent__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'parent.edit';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."parent_id" AS id FROM "app"."folders" r WHERE r."id" = $1 AND r."parent_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'folder', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'parent is a folder you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'parent is folder '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has edit' ELSE ', without edit' END;
      IF NOT ('folder:edit:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('folder:edit:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."users" "users" WHERE "users"."id" = $2::bigint
        AND true);
    WHEN 'service' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."services" "services" WHERE "services"."id" = $2::bigint
        AND true);
    WHEN 'project' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."projects" "projects" WHERE "projects"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('app.projects', 'select')) AND (coalesce("projects"."owner_id" = (SELECT authz.uid()), false)
    OR coalesce((public), false)
    OR EXISTS (SELECT 1 FROM authz_int."project__member" v WHERE v.id = "projects"."id")
    OR EXISTS (SELECT 1 FROM authz_int."project__service" v WHERE v.id = "projects"."id")));
    WHEN 'note' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."notes" "notes" WHERE "notes"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('app.notes', 'select')) AND EXISTS (SELECT 1 FROM authz_int."project__view" v WHERE v.id = "notes"."project_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."inbox" "inbox" WHERE "inbox"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('app.inbox', 'select')) AND coalesce("inbox"."recipient_id" = (SELECT authz.uid()), false));
    WHEN 'folder' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."folders" "folders" WHERE "folders"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('app.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"("folders"."parent_id")));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
<<authz__>>
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'service' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'project' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."project__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."project__view__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."note__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."note__view__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."message__read__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'project.member' THEN
      WITH want AS (SELECT DISTINCT x::bigint AS m FROM unnest($4) x),
      del AS (DELETE FROM "app"."members" s WHERE s."project_id" = $2::bigint AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "app"."members" ("project_id", "user_id") SELECT $2::bigint, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "app"."members" s WHERE s."project_id" = $2::bigint AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "app"."users") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('user', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('user', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'user'
                                                AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- the API keys of service rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."service__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "app"."services") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('service', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('service', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'service'
                                                AND NOT EXISTS (SELECT 1 FROM "app"."services" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('service', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('service', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."folders"', '"app"."inbox"', '"app"."notes"', '"app"."projects"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

REVOKE SELECT ON ALL TABLES IN SCHEMA authz_gen, authz_int FROM "conf_app";
GRANT SELECT ON authz_gen.policy_lines, authz_int."folder__edit", authz_int."folder__edit__direct", authz_int."project__edit", authz_int."project__member", authz_int."project__owner", authz_int."project__service", authz_int."project__view" TO "conf_app";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"conf_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."folder__edit"', 'authz_int."folder__edit__direct"', 'authz_int."project__edit"', 'authz_int."project__member"', 'authz_int."project__owner"', 'authz_int."project__service"', 'authz_int."project__view"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"conf_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"conf_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"conf_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.sign_out()', 'authz.connection_check()', 'authz.session_limited()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "conf_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]) LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f, 'conf_app');
  END LOOP;
END $gf$;

GRANT EXECUTE ON FUNCTION
  authz.uid(),
  authz.principal(),
